<?php
namespace App\Http\Controllers;
use App\Exports\ChequeReportExport;use App\Models\Cheque;use App\Services\ChequeAccessService;use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;use Maatwebsite\Excel\Facades\Excel;
class ChequeReportController extends Controller { public function index(Request$r,ChequeAccessService$a){$q=$a->scope(Cheque::with(['customer','supplier']),$r->user());$this->filters($q,$r);$summary=['count'=>(clone$q)->count(),'amount'=>(clone$q)->sum('amount'),'hold'=>(clone$q)->sum('hold_amount'),'passed'=>(clone$q)->sum('passed_amount'),'returned'=>(clone$q)->sum('returned_amount')];$cheques=$q->orderBy('cheque_date')->paginate(30)->withQueryString();return view('cheques.reports',compact('cheques','summary'));} public function filters($q,Request$r):void{$q->when($r->filled('type'),fn($x)=>$x->where('cheque_type',$r->type))->when($r->filled('status'),fn($x)=>$x->where('status',$r->status))->when($r->filled('bank'),fn($x)=>$x->where('bank_name','like','%'.$r->bank.'%'))->when($r->filled('cheque_number'),fn($x)=>$x->where('cheque_number','like','%'.$r->cheque_number.'%'))->when($r->filled('customer_id'),fn($x)=>$x->where('customer_id',$r->customer_id))->when($r->filled('supplier_id'),fn($x)=>$x->where('supplier_id',$r->supplier_id))->when($r->filled('lorry_id'),fn($x)=>$x->where('lorry_id',$r->lorry_id))->when($r->filled('store_id'),fn($x)=>$x->where('store_id',$r->store_id))->when($r->filled('from'),fn($x)=>$x->whereDate('cheque_date','>=',$r->from))->when($r->filled('to'),fn($x)=>$x->whereDate('cheque_date','<=',$r->to))->when($r->filled('min_amount'),fn($x)=>$x->where('amount','>=',$r->min_amount))->when($r->filled('max_amount'),fn($x)=>$x->where('amount','<=',$r->max_amount));} private function rows(Request$r,ChequeAccessService$a){$q=$a->scope(Cheque::with(['customer','supplier']),$r->user());$this->filters($q,$r);return$q->orderBy('cheque_date')->get();} public function pdf(Request$r,ChequeAccessService$a){abort_unless($r->user()->hasPermission('cheques.export_pdf'),403);return Pdf::loadView('cheques.report-pdf',['cheques'=>$this->rows($r,$a),'filters'=>$r->all()])->setPaper('a4','landscape')->download('cheque-report-'.today()->format('Ymd').'.pdf');} public function excel(Request$r,ChequeAccessService$a){abort_unless($r->user()->hasPermission('cheques.export_excel'),403);return Excel::download(new ChequeReportExport($this->rows($r,$a)),'cheque-report-'.today()->format('Ymd').'.xlsx');} }
